// ===== 常用 pnpm 命令 =====
// pnpm add <pkg> -w                  安装到根目录
// pnpm add <pkg> --filter @my/app    安装到指定包
// pnpm add @my/lib --filter @my/app  monorepo 内部包互相引用
// pnpm -r run build                  递归执行所有包的 build
// pnpm --filter @my/app... run build 只构建 @my/app 及其依赖
// pnpm -r --changed run test         只测试自上次发布以来有变更的包

